"use client";
// @zeus-internal
import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState } from "react";
import { animate, motion, useMotionValue, useReducedMotion, useTransform } from "motion/react";
import { ChevronDown, Menu, X } from "lucide-react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { DesktopContent, MobileMenu, type Group } from "./01-pill-groups/content";
export default function NavbarPillGroups() {
    const id = useId();
