    const open = active !== null && !mobile;
    const height = useMotionValue(0);
    const totalHeight = useTransform(height, value => geometry.height + value);
    const cancel = useCallback(() => { if (timer.current)
        clearTimeout(timer.current); timer.current = null; }, []);
    const choose = useCallback((group: Group | null) => { cancel(); if (group)
        setLast(group); setActive(group); }, [cancel]);
    const close = useCallback(() => { cancel(); setActive(null); setMobile(false); }, [cancel]);
    const leave = () => { cancel(); timer.current = setTimeout(() => setActive(null), 80); };
    useLayoutEffect(() => {
        const measure = () => {
            const header = headerRef.current?.getBoundingClientRect();
            const links = linksRef.current?.getBoundingClientRect();
            if (!header || !links)
                return;
            setGeometry({ top: links.top - header.top, width: links.width, height: links.height, content: contentRef.current?.getBoundingClientRect().height ?? 281 });
        };
        measure();
        const observer = new ResizeObserver(measure);
        if (linksRef.current)
            observer.observe(linksRef.current);
        if (contentRef.current)
            observer.observe(contentRef.current);
        window.addEventListener("resize", measure);
        return () => { observer.disconnect(); window.removeEventListener("resize", measure); };
    }, []);
    useEffect(() => {
        const control = animate(height, open ? geometry.content : 0, { duration: reduced ? 0 : 0.25, ease: ARTEMIS_EASE_OUT });
        return () => control.stop();
