            <div className="art:ml-auto art:@min-[768px]/artemis:order-3">
              <div className="art:hidden art:items-center art:whitespace-nowrap art:@min-[1024px]/artemis:flex art:gap-1 art:rounded-full art:bg-muted/60 art:p-1.5">
                <a href="#login" className="art:rounded-full art:px-2 art:py-2 art:text-sm art:text-muted-foreground art:hover:text-foreground art:focus-visible:outline-2 art:focus-visible:outline-ring">
                  {"Log in"}
                </a>
                <a href="#signup" className="art:rounded-full art:px-3 art:py-2 art:text-sm art:outline-none art:hover:text-primary art:focus-visible:ring-2 art:focus-visible:ring-ring">
                  {"Sign up"}
