import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../../lib/ease";
export type Group = "product" | "resources";
export const groups = {
    product: [
        { title: "Workspace", links: [["Projects", "projects"], ["Documents", "documents"], ["Collaboration", "collaboration"]] },
        { title: "Make it yours", links: [["Integrations", "integrations"], ["Automations", "automations"], ["Enterprise", "enterprise"]] },
    ],
    resources: [
        { title: "Learn", links: [["Guides", "guides"], ["Customer stories", "stories"], ["Journal", "journal"]] },
        { title: "Build", links: [["Documentation", "docs"], ["Templates", "templates"], ["What\u2019s new", "updates"]] },
    ],
} as const;
export function DesktopContent({ group, open, reduced, close }: {
    group: Group;
    open: boolean;
    reduced: boolean;
    close: () => void;
}) {
    const reveal = (delay: number) => ({
        initial: { opacity: 0, transform: "translateY(8px)" },
        animate: { opacity: open ? 1 : 0, transform: open ? "translateY(0px)" : "translateY(8px)" },
        transition: { duration: reduced ? 0 : open ? 0.2 : 0.1, delay: reduced || !open ? 0 : delay, ease: ARTEMIS_EASE_OUT },
    });
    return <motion.div className="art:mx-auto art:max-w-7xl art:p-6" initial={{ opacity: 0, transform: "translateY(0px)" }} animate={{ opacity: open ? 1 : 0 }} transition={{ duration: reduced ? 0 : open ? 0.2 : 0.1, delay: reduced || !open ? 0 : 0.035, ease: ARTEMIS_EASE_OUT }}>
    <div className="art:grid art:grid-cols-2 art:gap-x-4 art:gap-y-6" key={group}>
      {groups[group].map((column, i) => <div key={column.title}>
        <motion.h2 className="art:mb-3 art:font-mono art:text-xs art:uppercase art:tracking-widest art:text-muted-foreground" {...reveal(0.018 + i * 0.0075)}>{column.title}</motion.h2>
        <ul className="art:space-y-1">{column.links.map(([label, href], j) => <motion.li key={href} {...reveal(0.027 + i * 0.0075 + j * 0.0054)}>
          <a href={`#${href}`} onClick={close} className="art:-ml-2 art:block art:rounded-lg art:px-2 art:py-2 art:text-sm art:text-muted-foreground art:outline-none art:transition-colors art:hover:text-foreground art:focus-visible:ring-2 art:focus-visible:ring-ring">{label}</a>
        </motion.li>)}</ul>
      </div>)}
    </div>
    <motion.div key={`${group}-footer`} className="art:mt-8 art:flex art:flex-wrap art:items-center art:justify-between art:gap-3 art:border-t art:border-border art:pt-5" {...reveal(0.042)}>
      <p className="art:text-sm art:text-muted-foreground">A little guidance goes a long way.</p>
      <a href="#demo" onClick={close} className="art:flex art:items-center art:gap-2 art:rounded-full art:py-2 art:text-sm art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring">Book a demo<ArrowUpRight className="art:size-4"/></a>
    </motion.div>
  </motion.div>;
}
export function MobileMenu({ id, group, setGroup, reduced, close }: {
    id: string;
    group: Group | null;
    setGroup: (group: Group | null) => void;
    reduced: boolean;
    close: () => void;
}) {
    const press = { whileHover: reduced ? undefined : { scale: 1.01 }, whileTap: reduced ? undefined : { scale: 0.98 }, transition: ARTEMIS_SPRING_PRESS };
    return <motion.div id={`${id}-mobile`} className="art:absolute art:inset-x-0 art:top-full art:z-50 art:max-h-[70dvh] art:overflow-y-auto art:overscroll-contain art:rounded-b-2xl art:border-b art:border-border art:bg-background art:@min-[1024px]/artemis:hidden" initial={reduced ? false : { opacity: 0, y: -6 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: reduced ? 0 : 0.2, ease: ARTEMIS_EASE_OUT }}>
    <div className="art:divide-y art:divide-border art:px-5">
      {(["product", "resources"] as const).map(value => <div key={value}>
        <motion.button {...press} type="button" className="art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:flex art:min-h-14 art:w-full art:items-center art:justify-between art:text-base art:font-medium art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:rounded-full" aria-expanded={group === value} aria-controls={`${id}-mobile-${value}`} tabIndex={0} onClick={() => setGroup(group === value ? null : value)}>
          {value === "product" ? "Product" : "Resources"}<motion.span aria-hidden="true" animate={{ rotate: group === value ? 180 : 0 }} transition={{ duration: reduced ? 0 : 0.2, ease: "easeOut" }}><ChevronDown className="art:size-4"/></motion.span>
        </motion.button>
        {group === value && <motion.div id={`${id}-mobile-${value}`} className="art:pb-5" initial={reduced ? false : { opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: reduced ? 0 : 0.18, ease: ARTEMIS_EASE_OUT }}>
          <div className="art:grid art:grid-cols-2 art:gap-x-4 art:gap-y-5">{groups[value].map(column => <div key={column.title}>
            <h2 className="art:mb-2 art:text-xs art:font-medium art:text-muted-foreground">{column.title}</h2>
            <ul>{column.links.map(([label, href]) => <li key={href}><a href={`#${href}`} onClick={close} className="art:-ml-2 art:flex art:min-h-10 art:items-center art:rounded-lg art:px-2 art:py-2 art:text-sm art:leading-5 art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring">{label}</a></li>)}</ul>
