    </div>
    <a href="#signup" onClick={close} className="art:mx-5 art:flex art:min-h-12 art:items-center art:rounded-full art:text-sm art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring">Sign up</a>
    <div className="art:sticky art:bottom-0 art:grid art:grid-cols-2 art:gap-3 art:border-t art:border-border art:bg-background art:p-4">
      <motion.a {...press} href="#login" onClick={close} tabIndex={0} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full">Log in</motion.a>
      <motion.a {...press} href="#demo" onClick={close} tabIndex={0} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full">Book a demo</motion.a>
    </div>
  </motion.div>;
}

