// @zeus-internal
import type { KeyboardEvent } from "react";
export function artemisEscapeDismiss(event: KeyboardEvent<HTMLElement>, close: () => void) {
  if (event.key !== "Escape" || event.defaultPrevented) return;
  const triggers = [...event.currentTarget.querySelectorAll<HTMLButtonElement>('button[aria-expanded="true"]')];
  if (!triggers.length) return;
  const trigger = triggers.find(button => button.getClientRects().length > 0) ?? triggers[0];
  event.preventDefault();
  event.stopPropagation();
  close();
  trigger?.focus();
}
